import random

def door_lock_test(seed):
    # 가짜 벤치: 잠금 요청 뒤 상태 신호가 바뀌기까지 걸린 시간(ms). 가끔 버스가 바빠 늦어진다.
    rnd = random.Random(seed)
    return rnd.choice([80, 90, 95, 110, 260])

def speed_test(seed):
    return 40            # 늘 같은 답

def wake_test(seed):
    return 900           # 늘 한도를 넘는다(진짜 결함)

LIMIT = {"door_lock": 200, "speed": 100, "wake": 500}
TESTS = {"door_lock": door_lock_test, "speed": speed_test, "wake": wake_test}

for name, fn in TESTS.items():
    runs = [fn(seed) <= LIMIT[name] for seed in range(10)]   # 같은 시험을 10번
    p = sum(runs)
    verdict = "PASS" if p == 10 else "FAIL" if p == 0 else "FLAKY"
    print(f"{name:9s} 10번 중 통과 {p:2d} → {verdict}")
# door_lock 10번 중 통과  8 → FLAKY
# speed     10번 중 통과 10 → PASS
# wake      10번 중 통과  0 → FAIL
